from pathlib import Path
import subprocess,html
R=Path(__file__).parent
cards=[]
B='#eaf2ff';G='#e6f5ee';Y='#fff2d9';P='#f2e9ff'
def draw(name,title,caption,nodes,edges,rank='LR'):
 lines=['digraph G {',f'graph[rankdir={rank},bgcolor="white",pad="0.25",nodesep="0.4",ranksep="0.55"];','node[shape=box,style="rounded,filled",fontname="DejaVu Sans",fontsize=11,color="#6b8197",margin="0.15,0.1"];','edge[fontname="DejaVu Sans",fontsize=9,arrowsize=0.7];']
 for k,l,c in nodes:lines.append(f'{k}[label="{l}",fillcolor="{c}"];')
 for a,b,l,ctrl in edges:lines.append(f'{a}->{b}[label="{l}",'+('style=dashed,color="#986336"' if ctrl else 'color="#306d73",penwidth=1.3')+'];')
 lines+=['}'];(R/f'{name}.dot').write_text('\n'.join(lines))
 subprocess.run(['dot','-Tsvg',str(R/f'{name}.dot'),'-o',str(R/f'{name}.svg')],check=True)
 cards.append((name,title,caption))
draw('01_top','顶层：纯文本异构NPU','A53裸金属负责软件与地址；PL中的MPU、RPU、VPU各处理不同工作。图中的并行数量是综合目标，第三方芯片内部并非如此推定。',[
 ('cpu','A53 bare metal\nTokenizer / manifest / descriptors',Y),('ddr','PS DDR\nW4 body | native16 head\nKV | state journal | scratch',G),('ctrl','DCU / events / capability',Y),('dma','DMA\nRead / write / reorder / local mover',B),('local','Banked scratchpads\nWeights / partial / vectors / KV',G),('mpu','MPU\nW4 output parallel64\nNative A16 DOT32',B),('rpu','RPU\n16-lane FP32 recurrence',P),('cache','Head cache 3 x 64 KiB\nFetch / compute / writeback',G),('vpu','VPU16 + SFU4\nNorm / conv4 / gates / softplus',B),('out','A16 logits -> argmax\nToken / commit / fault',Y)],
 [('cpu','ddr','Load pure-text weights',False),('cpu','ctrl','CSR / task queue',True),('ctrl','dma','DMA commands',True),('ctrl','mpu','Linear / attention',True),('ctrl','rpu','State tasks',True),('ctrl','vpu','Vector tasks',True),('ddr','dma','AXI reads',False),('dma','ddr','AXI writes + B',False),('dma','local','Fill / store',False),('local','mpu','Operands',False),('mpu','local','Results',False),('local','vpu','Vectors',False),('vpu','local','Results',False),('dma','cache','Head DMA',False),('cache','rpu','FP32 old/new S',False),('vpu','rpu','Normalized q/k, beta/r',False),('rpu','vpu','o -> gated norm',False),('mpu','out','Head result stream',False),('out','ctrl','Done / fault',True)],rank='TB')
draw('02_mpu','MPU：两种主要数据流','W4输出并行适合decode；原生词表DOT32保持row-major连续读取。FP32 ADD fabric按模式复用，模式切换前排空。',[
 ('cmd','JobSequencer / mode / credits',Y),('w','W4 packed64 / scale cache',G),('x','A16 activation broadcast\nDecode1 / prefill4 queries',G),('prod','Shared x coefficient + INT4 select\n64 FP32 products',B),('acc','FP32 Add Fabric\n64 row partials, ctx=k mod C',B),('snap','Partial / group snapshots\nC=16, 2 slots',G),('reduce','One row/cycle group tree\n8 -> 4 -> 2 -> 1 ADD',B),('scale','ScaleApply2 / TotalBank2',B),('head','Native16 head row-major\n32 weights/cycle',G),('dot','A16 Product32 -> DOT32\n31 ADD reused from fabric',B),('rows','Multiple row contexts\nPartial -> final sum',G),('emit','A16 cast / output ACK\nArgmax or vector store',B)],
 [('cmd','prod','W4 mode',True),('w','prod','q',False),('x','prod','x',False),('prod','acc','Products',False),('acc','snap','Interleaved partials',False),('snap','reduce','16 partials/row',False),('reduce','scale','GroupSum',False),('w','scale','Aligned scale',False),('scale','emit','Linear result',False),('head','dot','Continuous 64B/cycle',False),('x','dot','x[K..K+31]',False),('cmd','dot','A16 DOT mode',True),('dot','rows','Row tagged DOTs',False),('rows','emit','Head logit',False)])
draw('03_rpu','RPU：一个head的两遍FP32处理','state为128×128 FP32；中间Sd留在片上，不重复扫DDR。所有head state写回确认后才发布token的新版本。',[
 ('ddr','DDR old/new state regions\n18 MiB each',G),('dma','DMA head fetch / writeback',B),('cache','Three 64 KiB head slots\n16 banks, j mod16',G),('coef','q / k / v / beta / r\nq,k normalization from VPU',Y),('p1','Pass1: Sd=r*S\nu=sum(k*Sd)',P),('delta','delta=beta*(v-u)',P),('p2','Pass2: Snew=Sd+k*delta\no=sum(q*Snew)',P),('o','A16 o -> gated norm',B),('commit','State B ACK + version commit',Y)],
 [('ddr','dma','Read old S',False),('dma','cache','Fill next head',False),('cache','p1','S',False),('coef','p1','r,k',False),('p1','cache','Local Sd',False),('p1','delta','u',False),('coef','delta','v,beta',False),('cache','p2','Sd',False),('delta','p2','delta',False),('coef','p2','q,k',False),('p2','cache','Dirty Snew',False),('p2','o','o',False),('cache','dma','Write previous dirty head',False),('dma','ddr','New S',False),('dma','commit','All B responses',True)])
draw('04_memory','存储与DMA：工作集和版本分离','PS DDR为默认模型存储；PL DDR是待测可选路径。原生输出head读取约508MB/token，是首要带宽段。逻辑容量不等于物理BRAM占用。',[
 ('pool','DDR region allocator\n64-bit physical addresses',Y),('weight','Canonical W4 body\n~258 MB incl scales/zeros',G),('head','Native16 embedding/head\n508 MB; alias to verify',G),('state','State old/new journal\n2 x 18 MiB',G),('kv','Full-attention KV\n48 MiB @4K',G),('scratch','Prefill hidden / QKV / z / o\nLifetime-managed DDR scratch',G),('rd','Read queues / ID / credit\n4 KiB burst split',B),('wr','Write queues / burst staging\nB-response tracking',B),('local','Local working set ~1.32 MiB\nHead slots / KV / FFN / partial',G),('param','Region limits / bank locks\nCache flush / invalidate',Y)],
 [('pool','weight','Allocate',True),('pool','head','Allocate',True),('pool','state','Allocate',True),('pool','kv','Allocate',True),('pool','scratch','Allocate',True),('weight','rd','Weight stream',False),('head','rd','Head stream',False),('state','rd','Old state',False),('kv','rd','Historical KV',False),('scratch','rd','Prefill loads',False),('rd','local','Reorder / pack / ready',False),('local','wr','Store / append',False),('wr','state','New state',False),('wr','kv','New token K/V',False),('wr','scratch','Scratch stores',False),('param','rd','Validate / reserve',True),('param','wr','Validate / reserve',True)])
draw('05_layer','混合层调度','18个linear layer走RPU；6个full layer走KV attention。Q投影包含gate，常规Norm使用1+weight，GDN输出另用gatedNorm。',[
 ('h','Hidden + residual',G),('norm','Zero-centered RMSNorm',B),('lp','Linear: W4 QKV/Z + A16 a/b',B),('conv','Conv4 + SiLU\nL2 q/k + beta/r',B),('rpu','RPU recurrence\nState old -> new',P),('gate','RMSNormGated(o,z)',B),('fp','Full: W4 Q+gate/K/V',B),('rope','Q/K norm + partial RoPE\nKV append',B),('att','QK -> online softmax -> PV',B),('fg','sigmoid(qGate) * attention',B),('op','W4 output projection\nResidual ADD',B),('ffn','Norm -> gate/up\nSiLU fence -> MUL fence -> down',B),('next','Residual ADD -> next layer\nAll state/KV/conv ACK -> commit',G)],
 [('h','norm','',False),('norm','lp','18 layers',False),('lp','conv','',False),('conv','rpu','',False),('rpu','gate','',False),('gate','op','',False),('norm','fp','6 layers',False),('fp','rope','',False),('rope','att','',False),('att','fg','',False),('fg','op','',False),('h','op','Residual',False),('op','ffn','',False),('ffn','next','',False)],rank='TB')
parts=['<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>MiniCPM 1B NPU</title><style>body{font-family:system-ui,sans-serif;background:#f3f6fa;color:#183047;margin:0}main{max-width:1500px;margin:auto;padding:24px}section{background:white;border:1px solid #dbe3ee;border-radius:12px;margin:24px 0;padding:20px}svg{width:100%;height:auto;min-width:600px}.canvas{overflow:auto}p{line-height:1.7}</style><main><h1>MiniCPM 1B 纯文本 NPU</h1><p>ZCU102 · 裸金属 · 200MHz目标 · 实线数据 / 虚线控制。设计图不是已实现RTL。</p>']
md=['# 架构图\n\n下载后打开`architecture.html`离线总览。实线数据、虚线控制。\n']
for n,t,c in cards:
 s=(R/f'{n}.svg').read_text();s=s[s.index('<svg'):]
 parts+=[f'<section><h2>{html.escape(t)}</h2><p>{html.escape(c)}</p><div class="canvas">{s}</div></section>']
 md+=[f'\n## {t}\n\n{c}\n\n![{t}]({n}.svg)\n']
parts+=['</main></html>'];(R/'architecture.html').write_text(''.join(parts));(R/'README.md').write_text('\n'.join(md))
print('Rendered 5 architecture diagrams and standalone HTML.')
